def transform(grid):
    # Grid is partitioned by 8 into 3x3 blocks. A marker colors its entire block;
    # color-2 markers additionally color all blocks in that same block column.
    h, w = len(grid), len(grid[0])
    rs = [i for i in range(h) if all(v == 8 for v in grid[i])]
    cs = [j for j in range(w) if all(grid[i][j] == 8 for i in range(h))]
    row_bounds = [-1] + rs + [h]
    col_bounds = [-1] + cs + [w]
    nr, nc = len(row_bounds)-1, len(col_bounds)-1
    out = [r[:] for r in grid]
    marks = {}
    for br in range(nr):
        for bc in range(nc):
            r0, r1 = row_bounds[br]+1, row_bounds[br+1]
            c0, c1 = col_bounds[bc]+1, col_bounds[bc+1]
            colors = {grid[r][c] for r in range(r0,r1) for c in range(c0,c1) if grid[r][c] not in (0,8)}
            if colors:
                marks[(br,bc)] = next(iter(colors))
    for (br,bc), color in marks.items():
        targets = [(br,bc)]
        if color == 2:
            targets += [(r,bc) for r in range(nr) if r != br]
        for rr,cc in targets:
            r0,r1=row_bounds[rr]+1,row_bounds[rr+1]
            c0,c1=col_bounds[cc]+1,col_bounds[cc+1]
            for r in range(r0,r1):
                for c in range(c0,c1): out[r][c]=color
    return out
